function Mark({ type }) {
  if (type === "x") {
    return (
      <svg className="mark mark-x" viewBox="0 0 100 100" aria-hidden="true">
        <path d="M25 25 75 75M75 25 25 75" />
      </svg>
    );
  }

  if (type === "o") {
    return (
      <svg className="mark mark-o" viewBox="0 0 100 100" aria-hidden="true">
        <circle cx="50" cy="50" r="32" />
      </svg>
    );
  }

  return null;
}

export default function Home() {
  return (
    <div className="page-shell">
      <header className="topbar">
        <a className="wordmark" href="#top" aria-label="Three in a Row home">
          <span className="wordmark-icon" aria-hidden="true"><i /><i /><i /></span>
          <span>THREE<br />IN A ROW</span>
        </a>
        <div className="local-label"><span className="local-dot" /> FRONTEND PREVIEW</div>
      </header>

      <main className="game-layout" id="top">
        <section className="intro" aria-labelledby="page-title">
          <p className="eyebrow">A CLASSIC GAME <span>NO. 01</span></p>
          <h1 id="page-title">Three<br />in a<br /><em>row.</em></h1>
          <p className="intro-copy">A little space for<br />some friendly rivalry.</p>
          <div className="how-to">
            <span className="how-to-mark" aria-hidden="true">✳</span>
            <span>PLAYER ONE<br />&amp; PLAYER TWO</span>
          </div>
        </section>

        <section className="play-area" aria-label="Tic tac toe board preview">
          <div className="game-heading">
            <div>
              <p className="eyebrow">THE BOARD <span>3 × 3</span></p>
              <h2>Ready when you are</h2>
            </div>
            <span className="turn-indicator" aria-hidden="true">✳</span>
          </div>

          <div className="board-frame">
            <div className="board" role="img" aria-label="Tic tac toe board preview with nine empty squares">
              {Array.from({ length: 9 }, (_, index) => (
                <div className="cell" key={index} aria-hidden="true">
                  <Mark type="" />
                </div>
              ))}
            </div>
          </div>

          <div className="game-footer">
            <p className="game-message">GAME BOARD PREVIEW</p>
            <button className="text-button" type="button" disabled>
              <svg viewBox="0 0 20 20" aria-hidden="true"><path d="M16.2 8A6.4 6.4 0 0 0 4.5 6.1L3 8m0 0V4.5M3 8h3.5M3.8 12a6.4 6.4 0 0 0 11.7 1.9L17 12m0 0v3.5M17 12h-3.5" /></svg>
              New round
            </button>
          </div>
        </section>

        <aside className="score-panel" aria-label="Scoreboard preview">
          <div className="score-heading">
            <p className="eyebrow">THE SCORE</p>
            <span className="score-rule" aria-hidden="true" />
          </div>
          <div className="score-row score-x">
            <span className="score-symbol" aria-hidden="true">X</span>
            <div className="score-player"><span>PLAYER ONE</span><strong>0</strong></div>
          </div>
          <div className="score-row score-o">
            <span className="score-symbol" aria-hidden="true">O</span>
            <div className="score-player"><span>PLAYER TWO</span><strong>0</strong></div>
          </div>
          <div className="draw-row"><span>Draws</span><strong>0</strong></div>
          <button className="reset-button" type="button" disabled>Reset score</button>
          <p className="score-note">SCOREBOARD PREVIEW<br />MATCH CONTROLS NOT CONNECTED</p>
        </aside>
      </main>

      <footer className="page-footer">
        <span>THE WORLD&apos;S SMALLEST STADIUM</span>
        <span>FRONTEND PREVIEW</span>
      </footer>
    </div>
  );
}